<style>
    .direct-sales{--b:#f4f7fb;--s:#fff;--ss:#f8fafc;--bd:#e2e8f0;--bds:#cbd5e1;--t:#0f172a;--m:#64748b;--p:#059669;--ps:#047857;--pf:#ecfdf5;--d:#e11d48;--df:#fff1f2;--blue:#2563eb;--sh:0 10px 30px rgba(15,23,42,.06);color:var(--t);background:var(--b);border:1px solid var(--bd);border-radius:22px;padding:18px}
    .dark .direct-sales{--b:#09090b;--s:#18181b;--ss:#111113;--bd:#2d2d32;--bds:#3f3f46;--t:#f4f4f5;--m:#a1a1aa;--p:#34d399;--ps:#34d399;--pf:rgba(6,78,59,.35);--d:#fb7185;--df:rgba(136,19,55,.25);--blue:#60a5fa;--sh:0 14px 34px rgba(0,0,0,.24)}
    .ds-workspace{display:grid;grid-template-columns:minmax(0,1fr) 390px;gap:18px;align-items:start}.ds-panel{background:var(--s);border:1px solid var(--bd);border-radius:18px;box-shadow:var(--sh)}.ds-catalog{min-width:0;padding:20px}.ds-checkout{padding:18px;position:sticky;top:16px}.ds-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:18px}.ds-title{margin:0;font-size:1.12rem;line-height:1.5;font-weight:900;color:var(--t)}.ds-subtitle{margin:3px 0 0;color:var(--m);font-size:.78rem;font-weight:600}.ds-section-label{display:block;margin-bottom:7px;color:var(--t);font-size:.76rem;font-weight:800}
    .ds-field{width:100%;min-height:42px;border:1px solid var(--bds);border-radius:11px;background:var(--s);color:var(--t);padding:8px 12px;font-size:.8rem;outline:none;transition:border-color .18s,box-shadow .18s}.ds-field::placeholder{color:var(--m)}.ds-field:focus{border-color:var(--p);box-shadow:0 0 0 3px color-mix(in srgb,var(--p) 16%,transparent)}.ds-search{position:relative;flex:1}.ds-search .ds-field{padding-inline-start:38px}.ds-search svg{position:absolute;inset-inline-start:12px;top:50%;width:18px;height:18px;color:var(--m);transform:translateY(-50%);pointer-events:none}.ds-toolbar{display:grid;grid-template-columns:minmax(180px,240px) minmax(220px,1fr);gap:12px;align-items:end;margin-bottom:16px}
    .ds-groups{display:flex;gap:8px;overflow-x:auto;padding:2px 2px 8px;scrollbar-width:thin;margin-bottom:14px}.ds-group{min-width:104px;max-width:140px;border:1px solid var(--bd);border-radius:12px;background:var(--ss);color:var(--t);padding:9px 10px;display:flex;align-items:center;gap:8px;cursor:pointer;transition:.18s ease}.ds-group:hover{border-color:var(--p);transform:translateY(-1px)}.ds-group.is-active{border-color:var(--p);background:var(--pf);color:var(--ps);box-shadow:inset 0 0 0 1px var(--p)}.ds-group-image{position:relative;width:34px;height:34px;border-radius:9px;background:var(--s);display:grid;place-items:center;overflow:hidden;flex:0 0 auto}.ds-group-image img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:var(--s)}.ds-group-image svg{width:18px;height:18px;color:var(--m)}.ds-group-name{font-size:.72rem;font-weight:800;line-height:1.35;overflow-wrap:anywhere}
    .ds-products{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px;max-height:650px;overflow-y:auto;padding:2px 2px 4px;scrollbar-width:thin;transition:opacity .15s}.ds-products.is-loading{opacity:.55}.ds-product{min-width:0;border:1px solid var(--bd);border-radius:14px;background:var(--s);padding:10px;display:flex;flex-direction:column;gap:8px;text-align:right;cursor:pointer;transition:transform .18s,border-color .18s,box-shadow .18s}.ds-product:hover{transform:translateY(-2px);border-color:var(--p);box-shadow:0 10px 22px rgba(15,23,42,.09)}.ds-product-image{position:relative;height:112px;border-radius:11px;background:var(--ss);display:grid;place-items:center;overflow:hidden}.ds-product-image img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;padding:7px;background:var(--ss)}.ds-product-image svg{width:32px;height:32px;color:var(--m)}.ds-product-name{min-height:38px;font-size:.82rem;font-weight:900;line-height:1.45;color:var(--t);overflow-wrap:anywhere}.ds-product-footer{display:flex;align-items:center;justify-content:space-between;gap:8px}.ds-price{color:var(--ps);font-size:.82rem;font-weight:900;white-space:nowrap}.ds-add{display:inline-flex;align-items:center;gap:4px;border-radius:8px;background:var(--pf);color:var(--ps);padding:5px 8px;font-size:.7rem;font-weight:900}.ds-empty{grid-column:1/-1;border:1px dashed var(--bds);border-radius:13px;color:var(--m);padding:36px 18px;text-align:center;font-size:.8rem;font-weight:700}
    .ds-cart-header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.ds-clear{border:1px solid color-mix(in srgb,var(--d) 35%,transparent);border-radius:9px;background:var(--df);color:var(--d);padding:6px 9px;font-size:.7rem;font-weight:900;cursor:pointer}.ds-cart{border:1px solid var(--bd);border-radius:13px;overflow:hidden;margin-bottom:15px;max-height:260px;overflow-y:auto}.ds-cart-head,.ds-cart-row{display:grid;grid-template-columns:minmax(0,1fr) 94px 72px 28px;gap:7px;align-items:center}.ds-cart-head{position:sticky;top:0;z-index:1;background:var(--ss);color:var(--m);padding:8px 10px;font-size:.67rem;font-weight:800}.ds-cart-row{padding:10px;border-top:1px solid var(--bd)}.ds-cart-name{min-width:0;font-size:.76rem;font-weight:900;color:var(--t);overflow-wrap:anywhere}.ds-cart-unit{color:var(--m);font-size:.64rem;margin-top:2px}.ds-quantity{display:grid;grid-template-columns:26px 1fr 26px;align-items:center;border:1px solid var(--bd);border-radius:9px;overflow:hidden;background:var(--ss)}.ds-quantity button{height:28px;border:0;background:transparent;color:var(--t);font-weight:900;cursor:pointer}.ds-quantity button:hover{background:var(--pf);color:var(--ps)}.ds-quantity span{text-align:center;font-size:.74rem;font-weight:900}.ds-row-total{text-align:center;color:var(--ps);font-size:.7rem;font-weight:900;white-space:nowrap}.ds-remove{border:0;background:transparent;color:var(--d);cursor:pointer;font-size:1rem;line-height:1}.ds-cart-empty{padding:25px 12px;text-align:center;color:var(--m);font-size:.76rem;font-weight:700}
    .ds-form{display:grid;gap:11px}.ds-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.ds-customer-fields{display:grid;grid-template-columns:1fr 1.2fr;gap:8px}.ds-checkbox{display:flex;align-items:flex-start;gap:8px;color:var(--m);font-size:.72rem;font-weight:700;cursor:pointer}.ds-checkbox input{margin-top:2px;accent-color:var(--p)}.ds-summary{margin-top:15px;border:1px solid var(--bd);border-radius:13px;background:var(--ss);padding:12px 14px}.ds-summary-row{display:flex;justify-content:space-between;align-items:center;gap:12px;color:var(--m);font-size:.76rem;padding:4px 0}.ds-summary-row strong{color:var(--t)}.ds-summary-row.is-total{margin-top:5px;padding-top:10px;border-top:1px solid var(--bd);color:var(--t);font-size:.92rem;font-weight:900}.ds-summary-row.is-total strong{color:var(--ps);font-size:1.05rem}.ds-change{color:var(--blue)!important}.ds-submit{width:100%;min-height:48px;margin-top:12px;border:0;border-radius:12px;background:var(--ps);color:#fff;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.86rem;font-weight:900;cursor:pointer;box-shadow:0 8px 18px color-mix(in srgb,var(--p) 22%,transparent);transition:transform .18s,filter .18s}.ds-submit:hover:not(:disabled){transform:translateY(-1px);filter:brightness(.96)}.ds-submit:disabled{background:var(--bds);color:var(--m);box-shadow:none;cursor:not-allowed}.ds-submit svg{width:19px;height:19px}
    @media(max-width:1100px){.ds-workspace{grid-template-columns:minmax(0,1fr) 350px}.ds-products{grid-template-columns:repeat(auto-fill,minmax(138px,1fr))}}
    @media(max-width:900px){.direct-sales{padding:12px;border-radius:16px}.ds-workspace{grid-template-columns:1fr}.ds-checkout{position:static}.ds-products{max-height:none}}
    @media(max-width:560px){.direct-sales{margin-inline:-12px;border-inline:0;border-radius:0;padding:10px}.ds-catalog,.ds-checkout{padding:13px;border-radius:15px}.ds-heading{margin-bottom:14px}.ds-toolbar,.ds-customer-fields{grid-template-columns:1fr}.ds-products{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.ds-product{padding:8px}.ds-product-image{height:92px}.ds-product-footer{align-items:flex-end}.ds-add{padding:4px 6px}.ds-cart-head{display:none}.ds-cart-row{grid-template-columns:minmax(0,1fr) 88px 62px 24px;padding:9px 8px}}
</style>
